int lego_usb_tower_init(struct usb_interface *interface, const struct usb_device_id *id)
{
    struct lego_usb_tower_dev *dev;
    int retval = -ENOMEM;

    dev = kzalloc(sizeof(*dev), GFP_KERNEL);
    if (!dev)
        return retval;

    mutex_init(&dev->lock);

    dev->interface = interface;
    dev->udev = usb_get_dev(interface_to_usbdev(interface));

    usb_set_intfdata(interface, dev);

    if (usb_find_endpoint_info(dev->udev, &dev->ep_in, &dev->ep_out) < 0) {
        dev_err(&dev->udev->dev, "Failed to find endpoint info.\n");
        goto error;
    }

    if (lego_usb_tower_get_firmware_version(dev) < 0) {
        dev_err(&dev->udev->dev, "Failed to get firmware version.\n");
        goto error;
    }

    return 0;

error:
    usb_set_intfdata(interface, NULL);
    usb_put_dev(dev->udev);
    kfree(dev);
    return retval;
}

int lego_usb_tower_init(struct usb_interface *interface, const struct usb_device_id *id) {
    struct lego_usb_tower_dev *dev;
    int retval = -ENOMEM;

    dev = kzalloc(sizeof(*dev), GFP_KERNEL);
    if (!dev)
        goto error;

    spin_lock_init(&dev->lock);

    dev->interface = interface;
    dev->udev = usb_get_dev(interface_to_usbdev(interface));

    usb_set_intfdata(interface, dev);

    if (lego_usb_tower_setup_endpoints(dev)) {
        dev_err(&interface->dev, "failed to setup endpoints\n");
        goto error;
    }

    if (lego_usb_tower_get_firmware_version(dev)) {
        dev_err(&interface->dev, "failed to get firmware version\n");
        goto error;
    }

    if (lego_usb_tower_register_device(dev)) {
        dev_err(&interface->dev, "failed to register device\n");
        goto error;
    }

    return 0;

error:
    lego_usb_tower_cleanup(dev);
    kfree(dev);
    return retval;
}

int lego_usb_tower_init(struct usb_interface *interface, const struct usb_device_id *id) {
    int result;
    struct usb_device *udev;
    struct lego_usb_tower_device *dev;

    udev = interface_to_usbdev(interface);

    dev = kzalloc(sizeof(*dev), GFP_KERNEL);
    if (!dev)
        return -ENOMEM;

    spin_lock_init(&dev->lock);

    result = usb_find_common_endpoints(interface, &dev->ep_in, &dev->ep_out, NULL, NULL);
    if (result < 0) {
        kfree(dev);
        return result;
    }

    result = usb_string(udev, udev->descriptor.iManufacturer, dev->manufacturer, sizeof(dev->manufacturer));
    if (!result)
        dev->has_manufacturer = true;

    result = usb_string(udev, udev->descriptor.iProduct, dev->product, sizeof(dev->product));
    if (!result)
        dev->has_product = true;

    result = usb_string(udev, udev->descriptor.iSerialNumber, dev->serial, sizeof(dev->serial));
    if (!result)
        dev->has_serial = true;

    dev->interface = interface;
    usb_set_intfdata(interface, dev);

    return 0;
}

int lego_usb_tower_probe(struct usb_interface *interface, const struct usb_device_id *id) {
    int result;
    struct lego_usb_tower_device *dev;

    dev = kzalloc(sizeof(*dev), GFP_KERNEL);
    if (!dev)
        return -ENOMEM;

    dev->interface = interface;
    usb_set_intfdata(interface, dev);

    dev->usb_dev = usb_get_dev(interface_to_usbdev(interface));
    usb_fill_int_urb(&dev->urb, dev->usb_dev, usb_rcvintpipe(dev->usb_dev, 1),
                     dev->in_buffer, LEGO_USB_TOWER_BUFFER_SIZE,
                     lego_usb_tower_irq, dev, dev->int_interval);

    result = usb_submit_urb(&dev->urb, GFP_KERNEL);
    if (result) {
        kfree(dev);
        return result;
    }

    result = lego_usb_tower_get_firmware_version(dev);
    if (result < 0) {
        usb_unlink_urb(&dev->urb);
        kfree(dev);
        return result;
    }

    return 0;
}

int lego_usb_tower_init(struct usb_interface *interface, const struct usb_device_id *id)
{
    int result = 0;
    struct lego_usb_tower_dev *dev = NULL;
    struct usb_device *usb_dev = NULL;
    struct usb_endpoint_descriptor *ep_desc = NULL;

    dev = kzalloc(sizeof(*dev), GFP_KERNEL);
    if (!dev)
        return -ENOMEM;

    usb_dev = interface_to_usbdev(interface);
    if (!usb_dev) {
        result = -ENODEV;
        goto free_dev;
    }

    dev->interface = interface;
    dev->usb_dev = usb_dev;

    dev->buf = usb_buffer_alloc(usb_dev, LEGO_USB_TOWER_BUFFER_SIZE, GFP_KERNEL, &dev->dma_addr);
    if (!dev->buf) {
        result = -ENOMEM;
        goto free_dev;
    }

    spin_lock_init(&dev->lock);

    for (int i = 0; i < USB_DIR_COUNT; i++) {
        ep_desc = &usb_dev->ep[i].desc;
        if ((ep_desc->bEndpointAddress & USB_ENDPOINT_DIR_MASK) == USB_DIR_OUT)
            dev->out_endpoint = &usb_dev->ep[i];
        else if ((ep_desc->bEndpointAddress & USB_ENDPOINT_DIR_MASK) == USB_DIR_IN)
            dev->in_endpoint = &usb_dev->ep[i];
    }

    if (!dev->out_endpoint || !dev->in_endpoint) {
        result = -ENODEV;
        goto free_buffers;
    }

    result = usb_register_dev(interface, &lego_usb_tower_class);
    if (result < 0) {
        dev_err(&interface->dev, "Failed to register USB device: %d\n", result);
        goto free_buffers;
    }

    result = lego_usb_tower_get_fw_version(dev);
    if (result < 0) {
        dev_err(&interface->dev, "Failed to get firmware version: %d\n", result);
        goto unregister_dev;
    }

    usb_set_intfdata(interface, dev);
    return 0;

unregister_dev:
    usb_deregister_dev(interface, &lego_usb_tower_class);
free_buffers:
    usb_buffer_free(usb_dev, LEGO_USB_TOWER_BUFFER_SIZE, dev->buf, dev->dma_addr);
free_dev:
    kfree(dev);
    return result;
}
